contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller) public {
        require(caller != address(this), "caller must differ from this");

        bool reverted;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run() public payable {
        require(address(this).balance >= 0);
        address ownerBefore = c.smartfix_owner();
        address deployer = address(this);
        bool reverted;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }
        address ownerAfter = c.smartfix_owner();
        assert(ownerBefore == deployer && ownerAfter == ownerBefore && !reverted);
    }

    receive() external payable {}
}
